INSERT IGNORE INTO books (id, title, author, price, image, rating, rating_count, publisher, publish_date, pages, isbn, description) VALUES
(1, 'JavaScript高级程序设计', '尼古拉斯·扎卡斯', 99.00, 'https://file.ituring.com.cn/LargeCover/20080d81a4fb8a268c40', 5, 120, '人民邮电出版社', '2020-01-01', 768, '9787115528039', '《JavaScript高级程序设计》是一本面向中级到高级JavaScript开发人员的专业书籍，全面介绍了JavaScript语言的核心概念、技术和最佳实践。本书涵盖了JavaScript的语法、DOM操作、事件处理、面向对象编程、异步编程、Canvas绘图等内容，是JavaScript开发者的必备参考书籍。<br><br>本书由尼古拉斯·扎卡斯撰写，他是一位知名的前端技术专家，拥有丰富的JavaScript开发经验。本书内容深入浅出，适合有一定编程基础的开发者阅读，通过学习本书，读者可以掌握JavaScript的高级特性，提高代码质量和开发效率。'),
(2, 'Python编程：从入门到实践', '埃里克·马瑟斯', 89.00, 'https://file.ituring.com.cn/LargeCover/23047b0f0134221867e2', 4.5, 98, '人民邮电出版社', '2019-10-01', 448, '9787115428028', '《Python编程：从入门到实践》是一本面向初学者的Python编程入门书籍，通过实际项目帮助读者学习Python编程。本书涵盖了Python的基本语法、数据结构、函数、类、文件操作等内容，并通过三个完整的项目（外星人入侵游戏、数据可视化、Web应用）帮助读者巩固所学知识。'),
(3, '深入理解计算机系统', 'Randal E. Bryant', 129.00, 'https://img12.360buyimg.com/n1/jfs/t1/328223/32/18971/145043/68c3d0f2Fc1141045/610b642b09eb064e.jpg', 5, 156, '机械工业出版社', '2016-01-01', 720, '9787111407010', '《深入理解计算机系统》是一本系统介绍计算机系统的书籍，涵盖了计算机的硬件和软件方面的知识。本书从程序员的角度出发，介绍了计算机系统的各个层次，包括硬件结构、指令系统、操作系统、编译系统等内容，帮助读者理解程序在计算机系统中是如何执行的。'),
(4, '算法导论', 'Thomas H. Cormen', 119.00, 'https://cdn.how2cs.cn/csguide/%E7%AE%97%E6%B3%95%E5%AF%BC%E8%AE%BA.jpg', 4.5, 87, '机械工业出版社', '2013-01-01', 780, '9787111407010', '《算法导论》是一本经典的算法教材，全面介绍了各种算法的设计和分析方法。本书涵盖了排序、搜索、图算法、动态规划、贪心算法等内容，并对每种算法的时间复杂度和空间复杂度进行了详细分析，是算法学习的权威参考书籍。'),
(5, '红楼梦', '曹雪芹', 98.00, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRgUTr2lWLRz5u7mnRXvQzuY3JDFXahuO7LVQ&s', 5, 256, '人民文学出版社', '2008-07-01', 1200, '9787020002207', '《红楼梦》是中国古典四大名著之一，由清代作家曹雪芹创作。小说以贾、史、王、薛四大家族的兴衰为背景，以贾宝玉、林黛玉、薛宝钗的爱情婚姻悲剧为主线，描绘了一群举止见识高于须眉之上的闺阁佳人的人生百态，展现了真正的人性美和悲剧美。'),
(6, '三国演义', '罗贯中', 88.00, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTkW6B4l1se4_82SdRABMen0IkJtWqORGCpuQ&s', 4.5, 234, '人民文学出版社', '2008-07-01', 960, '9787020002207', '《三国演义》是中国古典四大名著之一，由明代作家罗贯中创作。小说描写了从东汉末年到西晋初年之间近百年的历史风云，以描写战争为主，诉说了东汉末年的群雄割据混战和魏、蜀、吴三国之间的政治和军事斗争，最终司马炎一统三国，建立晋朝的故事。'),
(7, '水浒传', '施耐庵', 85.00, 'https://static.airchina.com.cn/upload/t/jWuZv5etyRvOB6L_a8mpHZ426gE=/670x670/img/store/438/1652348073012..jpg', 4.5, 212, '人民文学出版社', '2008-07-01', 1000, '9787020002207', '《水浒传》是中国古典四大名著之一，由元末明初作家施耐庵创作。小说描写了北宋末年以宋江为首的108位好汉在梁山聚义，以及聚义之后接受招安、四处征战的故事。全书通过描写梁山好汉反抗欺压、水泊梁山壮大和受宋朝招安，以及受招安后为宋朝征战，最终消亡的宏大故事。'),
(8, '西游记', '吴承恩', 82.00, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQTa0_DE8rbWzyEdAUWtmRV3ZEwi-elqwKLQQ&s', 5, 268, '人民文学出版社', '2008-07-01', 880, '9787020002207', '《西游记》是中国古典四大名著之一，由明代作家吴承恩创作。小说描写了唐僧师徒四人西天取经的故事，一路上历经九九八十一难，降妖伏魔，最终取得真经。这本书是中国古代第一部浪漫主义章回体长篇神魔小说，充满了奇幻色彩和深刻的哲理。'),
(9, '百年孤独', '加西亚·马尔克斯', 78.00, 'https://m.media-amazon.com/images/I/41ZAmA+408L._AC_UF1000,1000_QL80_.jpg', 4.5, 189, '南海出版公司', '2017-08-01', 360, '9787544291170', '《百年孤独》是哥伦比亚作家加西亚·马尔克斯的代表作，也是拉丁美洲魔幻现实主义文学的代表作。小说讲述了布恩迪亚家族七代人的传奇故事，以及加勒比海沿岸小镇马孔多的百年兴衰，反映了拉丁美洲一个世纪以来风云变幻的历史。'),
(10, '巴黎圣母院', '维克多·雨果', 75.00, 'https://piccdn3.umiwi.com/img/201902/27/201902270158200726868926.jpg?x-oss-process=image/resize,m_fill,h_320,w_240', 4.5, 178, '人民文学出版社', '2018-05-01', 420, '9787020002207', '《巴黎圣母院》是法国作家维克多·雨果的代表作之一。小说以15世纪的巴黎为背景，讲述了巴黎圣母院的敲钟人卡西莫多、副主教克洛德·弗罗洛和吉卜赛女郎埃斯梅拉达之间的爱情悲剧。这部小说揭露了宗教的虚伪，宣告了禁欲主义的破产，歌颂了下层劳动人民的善良、友爱、舍己为人的优秀品质。');
INSERT IGNORE INTO reviews (id, book_id, name, rating, date, content) VALUES
(1, 1, '张三', '★★★★★', '2026-03-01', '这本书非常棒，内容全面且深入，是JavaScript开发者的必读书籍。作者讲解清晰，示例丰富，非常适合学习JavaScript的高级特性。'),
(2, 1, '李四', '★★★★☆', '2026-02-15', '内容很详细，但是有些地方比较难懂，需要反复阅读。不过总体来说是一本非常好的JavaScript书籍。'),
(3, 2, '王五', '★★★★★', '2026-03-05', '这本书非常适合Python初学者，作者讲解清晰，示例丰富，通过实际项目学习非常有帮助。'),
(4, 2, '赵六', '★★★★☆', '2026-02-20', '内容很基础，适合入门，但是对于有一定编程基础的人来说可能有点简单。'),
(5, 3, '孙七', '★★★★★', '2026-03-10', '这本书是计算机专业学生的必读书籍，内容全面且深入，讲解清晰，帮助我更好地理解计算机系统的工作原理。'),
(6, 3, '周八', '★★★★☆', '2026-02-25', '内容有点难度，需要一定的计算机基础，但是非常值得一读。'),
(7, 4, '吴九', '★★★★★', '2026-03-12', '这本书是算法学习的经典教材，内容全面，讲解详细，是计算机专业学生的必读书籍。'),
(8, 4, '郑十', '★★★★☆', '2026-02-28', '内容比较理论化，需要一定的数学基础，但是对于理解算法的原理非常有帮助。'),
(9, 5, '林黛玉', '★★★★★', '2026-03-01', '满纸荒唐言，一把辛酸泪。都云作者痴，谁解其中味？'),
(10, 5, '贾宝玉', '★★★★★', '2026-02-15', '假作真时真亦假，无为有处有还无。'),
(11, 6, '诸葛亮', '★★★★★', '2026-03-05', '鞠躬尽瘁，死而后已。'),
(12, 6, '曹操', '★★★★☆', '2026-02-20', '宁教我负天下人，休教天下人负我。'),
(13, 7, '宋江', '★★★★★', '2026-03-10', '忠义堂前绣字红旗后，一书''山东呼保义''，一书''河北玉麒麟''。'),
(14, 7, '武松', '★★★★☆', '2026-02-25', '酒壮英雄胆，打虎景阳冈。'),
(15, 8, '孙悟空', '★★★★★', '2026-03-12', '俺老孙来也！'),
(16, 8, '猪八戒', '★★★★☆', '2026-02-28', '大师兄，师傅被妖怪抓走了！'),
(17, 9, '马尔克斯', '★★★★★', '2026-03-08', '许多年后，奥雷良诺上校站在行刑队面前，准会想起父亲带他去参观冰块的那个遥远的下午。'),
(18, 9, '读者', '★★★★☆', '2026-02-22', '魔幻现实主义的巅峰之作，每一页都充满了惊喜。'),
(19, 10, '维克多·雨果', '★★★★★', '2026-03-13', '丑在美的旁边，畸形靠近着优美，丑怪藏在崇高背后，美与丑并存，光明与黑暗相共。'),
(20, 10, '读者', '★★★★☆', '2026-02-29', '卡西莫多的形象让人难忘，这是一部关于爱与美的经典之作。');